<script setup>
import { Head, useForm } from '@inertiajs/vue3';
import AppLayout from '../../Layouts/AppLayout.vue';
import Errors from '../../Components/Errors.vue';
defineProps({preview:{type:Object,default:null},collections:{type:Array,default:()=>[]}});
const form=useForm({file:null,term_column:0,definition_column:1,has_header:true});
const save=useForm({collection_id:''});
const upload=()=>form.post('/imports/preview',{forceFormData:true});
</script>
<template><Head title="Import words"/><AppLayout title="Bring your words along." subtitle="From a spreadsheet to your next study session."><div class="import-grid"><section class="panel"><span class="step-label">01 / UPLOAD & MAP</span><h2>A CSV full of possibilities.</h2><p class="muted">Choose a UTF-8 CSV with a word column and a definition column. Preview everything before importing.</p><form @submit.prevent="upload"><Errors :errors="form.errors"/><label class="upload-zone"><span class="upload-icon">↥</span><strong>{{form.file?.name || 'Choose a CSV file'}}</strong><small>Up to 2 MB · .csv or .txt</small><input type="file" accept=".csv,.txt,text/csv,text/plain" @change="form.file=$event.target.files[0]" required/></label><div class="two-col"><label>Word column<select v-model.number="form.term_column"><option v-for="n in 20" :key="n" :value="n-1">Column {{n}}</option></select></label><label>Definition column<select v-model.number="form.definition_column"><option v-for="n in 20" :key="n" :value="n-1">Column {{n}}</option></select></label></div><label class="check"><input type="checkbox" v-model="form.has_header"/> First row contains column headings</label><div class="form-actions"><button class="button" :disabled="form.processing">{{form.processing?'Reading file…':'Preview import →'}}</button></div></form></section><aside class="import-help"><span class="eyebrow">A SIMPLE START</span><h3>Two columns.<br>A whole new collection.</h3><pre>term,definition
curious,eager to learn
resilient,able to recover</pre><p>Your original words and definitions stay as they are. Add your own translations as private notes later.</p><p>Exact duplicates in your word pool are skipped, not overwritten.</p></aside></div><section v-if="preview" class="panel preview"><span class="step-label">02 / REVIEW & IMPORT</span><div class="section-heading"><h2>Looking good?</h2><span class="pill dark">{{preview.total}} rows · {{preview.duplicates??0}} duplicates</span></div><p v-if="preview.headers?.length" class="muted small">Columns: {{preview.headers.join(' · ')}}</p><div class="preview-table"><table><thead><tr><th>Word</th><th>Definition</th></tr></thead><tbody><tr v-for="(row,index) in preview.rows" :key="index"><td>{{row.term}}</td><td>{{row.definition}}</td></tr></tbody></table></div><p class="muted small">Preview may show only the first rows. The validated import contains {{preview.total}} rows.</p><form @submit.prevent="save.post('/imports/store')"><Errors :errors="save.errors"/><label v-if="collections.length">Also add to a collection<select v-model="save.collection_id"><option value="">Word pool only</option><option v-for="c in collections" :key="c.id" :value="c.id">{{c.title}}</option></select></label><div class="form-actions"><button class="button" :disabled="save.processing">{{save.processing?'Importing…':'Import into my pool'}}</button></div></form></section></AppLayout></template>
